import json, sys, numpy as np
data = json.loads(json.loads(sys.stdin.read())['result'])
exps = data['data']['experiments']

# Get ALL full_occ_ln eval experiments with full metrics
for k, v in exps.items():
    if 'full_occ_ln' in k and 'eval' in k:
        m = v.get('metrics', {})
        # Try to find CAR in various places
        car = m.get('CAR', m.get('car', None))
        if car is None and 'at_50000_50r' in m:
            car = m['at_50000_50r'].get('CAR', None)
        if car is None and 'per_task' in m:
            pt = m['per_task']
            if pt:
                cars = [t.get('car', t.get('CAR', 0)) for t in (pt.values() if isinstance(pt, dict) else [])]
                if cars:
                    car = np.mean(cars)
        print(f'{k}: CAR={car}, keys={list(m.keys())[:5]}')

# Also get detach_bn v2 evals
print()
for k, v in exps.items():
    if 'detach_bn_v2' in k and 'eval' in k:
        m = v.get('metrics', {})
        car = m.get('CAR', m.get('car', None))
        if car is None and 'at_50000_50r' in m:
            car = m['at_50000_50r'].get('CAR', None)
